import { findingReviewSummary } from '../shared/report-format.mjs';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={confirmed:'Подтверждено',rejected:'Отклонено',modified:'Изменено'},marker='РАССМОТРЕНИЕ ЗАМЕЧАНИЙ';
export function readExpertDecisions(text=''){const records=new Map();for(const m of text.matchAll(/^Замечание (\d+) — (Подтверждено|Отклонено|Изменено)(?:\n|$)([\s\S]*?)(?=^Замечание \d+ — |^СОБСТВЕННЫЕ ЗАМЕЧАНИЯ|^ВЫВОД ЭКСПЕРТА|$(?![\s\S]))/gm))records.set(Number(m[1]),{status:Object.keys(titles).find(k=>titles[k]===m[2]),comment:m[3].trim()});return records;}
export function withExpertDecision(text,index,status,comment){if(!titles[status])throw Error('Неизвестное решение');const records=readExpertDecisions(text);records.set(index,{status,comment:comment.trim()});const [body,...parts]=text.split('\n'+marker+'\n'),tail=parts.join('\n'+marker+'\n');let extra='';const matches=[tail.indexOf('СОБСТВЕННЫЕ ЗАМЕЧАНИЯ'),tail.indexOf('ВЫВОД ЭКСПЕРТА')].filter(i=>i>=0);if(matches.length)extra='\n\n'+tail.slice(Math.min(...matches));return body.trim()+'\n\n'+marker+'\n'+[...records].sort((a,b)=>a[0]-b[0]).map(([i,r])=>'Замечание '+i+' — '+titles[r.status]+'\n'+r.comment).join('\n\n')+extra;}
export function ownQuotes(text=''){return [...text.replaceAll('\\n','\n').matchAll(/Фрагмент \/ пункт: ([\s\S]*?)\nПравовая оценка:/g)].map(m=>m[1].trim()).filter(Boolean);}
export function highlightedDocument(text,findings,expertQuotes=[]){
 const spans=[];
 for(const [source,quotes] of [['ai',findings.map(f=>f.quote)],['expert',expertQuotes]])quotes.forEach((quote,index)=>{if(!quote)return;const start=text.indexOf(quote);if(start>=0)spans.push({start,end:start+quote.length,source,index});});
 const points=[...new Set([0,text.length,...spans.flatMap(s=>[s.start,s.end])])].sort((a,b)=>a-b);
 return points.slice(0,-1).map((start,i)=>{const end=points[i+1],active=spans.filter(s=>s.start<=start&&s.end>=end);const part=esc(text.slice(start,end));if(!active.length)return part;const sources=[...new Set(active.map(s=>s.source))];return '<mark class="'+sources.map(s=>'quote-'+s).join(' ')+'">'+active.map(s=>'<span class="quote-source" tabindex="0" role="button" data-scroll-to="'+(s.source==='ai'?'expert-finding-'+s.index:'expert-own-findings')+'" aria-label="Открыть замечание '+(s.source==='ai'?'ИИ':'эксперта')+' '+(s.index+1)+'">'+(s.source==='ai'?'ИИ':'Эксперт')+'</span>').join('')+part+'</mark>';}).join('');
}
export function expertReviewPanel(c){
 const latest=c.conclusions.at(-1),editable=!c.archivedAt&&(!c.queued||c.startedAt)&&c.role==='expert'&&latest?.status==='draft',records=readExpertDecisions(latest?.text||'');
 const own=[...(latest?.text||'').replaceAll('\\n','\n').matchAll(/^СОБСТВЕННЫЕ ЗАМЕЧАНИЯ\n([\s\S]*?)(?=^СОБСТВЕННЫЕ ЗАМЕЧАНИЯ|^ВЫВОД ЭКСПЕРТА|^РАССМОТРЕНИЕ ЗАМЕЧАНИЙ|$(?![\s\S]))/gm)].map(m=>m[1].trim()).filter(Boolean);
 return `<section class="expert-review-panel"><section class="card expert-own-findings" id="expert-own-findings"><h2>Собственные замечания независимого эксперта</h2><p class="muted">Автор: ${esc(c.expertProfile?.name||'Эксперт ещё не назначен')}</p>${own.map(t=>`<div class="conclusion-text">${esc(t)}</div>`).join('')||'<p>Собственные замечания эксперта пока не добавлены.</p>'}<p>Заключение эксперта доступно в отдельном разделе «Заключение».</p></section><p data-expert-review-counter role="status"></p><p class="case-review-caption">Результаты ИИ: ${c.run.findings.length}. Сохранённый снимок анализа — материал для эксперта. Решения и комментарии эксперта отмечены отдельно.</p><div class="expert-review-layout"><div class="expert-document-column"><div class="case-column-heading"><h2>Документ</h2></div><div class="expert-document" id="expert-document">${highlightedDocument(c.document.text,c.run.findings,ownQuotes(latest?.text))}</div>${editable?'<button type="button" class="btn compact expert-own-button" data-expert-own>Добавить своё замечание</button> <button type="button" class="btn compact" data-case-go-conclusion>Перейти к заключению</button><p class="case-field-hint" data-own-help role="status" hidden>Выделите фрагмент документа и нажмите кнопку.</p>':''}</div><div class="expert-findings-column">${editable?ownFindingForm():''}<div class="case-column-heading"><h2>Результаты ИИ</h2></div><div class="expert-findings-list">${c.run.findings.map((f,i)=>`<article id="expert-finding-${i}" class="card expert-finding"><div class="expert-finding-head"><h3>Замечание ИИ ${i+1}</h3><span class="status" data-expert-status="${i+1}">Решение эксперта: ${esc((records.get(i+1)?.status==='rejected'?'Отклонено с комментарием':titles[records.get(i+1)?.status])||'Эксперт ещё не рассмотрел')}</span></div><p class="expert-finding-point">Пункт ${esc(f.point)}</p><blockquote>${esc(f.quote)}</blockquote>${f.review?.documentAssessment?'':`<p class="expert-finding-explanation">${esc(f.explanation)}</p>`}${findingReviewSummary(f).map(([label,value])=>`<p><strong>${esc(label)}</strong> · ${esc(value)}</p>`).join('')}${editable?`<label class="field"><span>Комментарий эксперта или исправленная редакция</span><textarea data-expert-comment="${i+1}" rows="2" maxlength="3000">${esc(records.get(i+1)?.comment||'')}</textarea></label><div class="expert-verdicts">${Object.entries(titles).map(([status])=>`<button type="button" class="btn compact" data-expert-verdict="${status}" data-index="${i+1}" aria-pressed="${records.get(i+1)?.status===status}">${({confirmed:'Подтвердить',rejected:'Отклонить',modified:'Изменить'})[status]}</button>`).join('')}</div>`:records.get(i+1)?.comment?'<p class="expert-record-comment"><strong>Комментарий эксперта:</strong> '+esc(records.get(i+1).comment)+'</p>':''}<details class="finding-evidence"><summary>Обоснование и рекомендации</summary>${f.review?.documentAssessment?`<p><strong>Исходное замечание Аналитика</strong> · ${esc(f.explanation)}</p>`:''}${f.editor?.proposal?'<p><strong>Проект правки ИИ:</strong> '+esc(f.editor.proposal)+'</p>':''}${f.editor?.requiresLegalReview?'<p>Проект требует сверки с применимыми нормами.</p>':''}${f.editor?.explanation?'<p><strong>Пояснение Редактора:</strong> '+esc(f.editor.explanation)+'</p>':''}${f.review?'<p><strong>Перепроверка ИИ:</strong> '+esc(({supported:'Выдержала перепроверку',contested:'Есть возражение',insufficient:'Недостаточно данных'})[f.review.verdict]||'Не выполнена')+'</p><p>'+esc(f.review.explanation||'')+'</p>'+((f.review.counterarguments||[]).length?'<ul>'+f.review.counterarguments.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':''):''}<p><strong>Решение автора документа:</strong> ${esc(({confirmed:'Подтверждено',modified:'Изменено',rejected:'Отклонено',pending:'Не рассмотрено'})[f.decision?.status]||'Не принято')}</p>${['explanation','proposal','comment','basis'].filter(k=>f.decision?.[k]).map(k=>'<p><strong>'+({explanation:'Объяснение',proposal:'Редакция автора',comment:'Комментарий автора',basis:'Основание автора'})[k]+':</strong> '+esc(f.decision[k])+'</p>').join('')}${(f.basis||[]).map(b=>'<blockquote>'+esc(b.quote)+'</blockquote>').join('')||'<p>Правовые основания ИИ не предоставлены.</p>'}</details></article>`).join('')||'<div class="card"><h3>Замечания ИИ отсутствуют</h3><p>Документ доступен для самостоятельной проверки.</p></div>'}</div></div></div></section>`;
}
export function ownFindingForm(){return '<section id="expert-own-form" class="card stack" hidden><h2>Своё замечание</h2><label class="field"><span>Фрагмент / пункт</span><textarea data-own-quote rows="3" maxlength="5000" required></textarea></label><label class="field"><span>Правовая оценка</span><textarea data-own-assessment rows="4" maxlength="3000" required></textarea></label><label class="field"><span>Рекомендация</span><textarea data-own-recommendation rows="3" maxlength="3000" required></textarea></label><p data-own-status role="status"></p><div><button type="button" class="btn primary" data-own-save>Сохранить замечание</button> <button type="button" class="btn" data-own-cancel>Отмена</button></div></section>';}
export function conclusionSection(outcome,comment){return 'ВЫВОД ЭКСПЕРТА\n'+outcome+'\nРекомендации: '+comment.trim();}
export function composeConclusion(text,outcome,comment){
 const body=text.replace(/^ВЫВОД ЭКСПЕРТА\n[\s\S]*?(?=^РАССМОТРЕНИЕ ЗАМЕЧАНИЙ\n|^СОБСТВЕННЫЕ ЗАМЕЧАНИЯ\n|$(?![\s\S]))/gm,'').trimEnd();
 return (body?body+'\n\n':'')+conclusionSection(outcome,comment);
}
export function conclusionTools(){return '<div class="conclusion-tools"><fieldset id="expert-outcome" class="field" style="border:0;padding:0;margin:0"><legend>Мнение эксперта</legend><label style="display:flex;gap:10px;align-items:center;padding:12px;border-radius:8px;background:#dcf4e6;color:#11633b"><input type="radio" name="expert-outcome" value="Низкий потенциал коррупциогенности · даны комментарии" style="width:auto;accent-color:#11633b">Низкий потенциал коррупциогенности · даны комментарии</label><label style="display:flex;gap:10px;align-items:center;padding:12px;border-radius:8px;background:#fff3d0;color:#705000"><input type="radio" name="expert-outcome" value="Средний потенциал коррупциогенности · требует доработки" style="width:auto;accent-color:#705000">Средний потенциал коррупциогенности · требует доработки</label><label style="display:flex;gap:10px;align-items:center;padding:12px;border-radius:8px;background:#fdebef;color:#b71936"><input type="radio" name="expert-outcome" value="Высокий потенциал коррупциогенности · требует переработки" style="width:auto;accent-color:#b71936">Высокий потенциал коррупциогенности · требует переработки</label></fieldset><label class="field"><span>Рекомендации</span><textarea id="expert-recommendations" rows="3" maxlength="5000"></textarea></label><button class="btn compact" type="button" data-expert-compose>Сформировать заключение</button><p id="expert-save-indicator" class="save-indicator" role="status">Черновик сохраняется автоматически каждые 30 секунд.</p><p id="expert-review-counter" role="status"></p></div>';}
export function activateCaseTab(tab,root){if(!root||!['review','conclusion','discussion'].includes(tab))return false;for(const button of root.querySelectorAll('[data-case-tab]')){const selected=button.dataset.caseTab===tab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;button.classList.toggle('primary',selected);}for(const panel of root.querySelectorAll('[data-case-panel]'))panel.hidden=panel.dataset.casePanel!==tab;return true;}
export function installExpertEditor({getCase,save,onDirty,onSaved,onTab}){let saving=false,selection='';const generated=new WeakMap();const form=()=>document.getElementById('expert-draft-form');const update=()=>{const f=form(),c=getCase();if(!f||!c)return;const records=readExpertDecisions(f.elements.text.value);let done=0;for(let i=1;i<=c.run.findings.length;i++)if(records.has(i))done++;const counter=document.getElementById('expert-review-counter');if(counter)counter.textContent='Рассмотрено '+done+' из '+c.run.findings.length;for(const node of document.querySelectorAll('[data-expert-review-counter]'))node.textContent='Рассмотрено '+done+' из '+c.run.findings.length;const sign=document.querySelector('[data-action="expert-sign"]');if(sign)sign.disabled=done<c.run.findings.length;};const change=text=>{const f=form();if(!f)return;f.elements.text.value=text;f.elements.text.dispatchEvent(new Event('input',{bubbles:true}));update();};const message=text=>{const node=document.getElementById('expert-save-indicator');if(node)node.textContent=text;};
 document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-case-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const root=tab.closest('.expert-case-view'),tabs=[...root.querySelectorAll('[data-case-tab]')],index=tabs.indexOf(tab),next=e.key==='Home'?tabs[0]:e.key==='End'?tabs.at(-1):tabs[(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];e.preventDefault();if(activateCaseTab(next.dataset.caseTab,root)){onTab?.(root.dataset.caseId,next.dataset.caseTab);next.focus();}});

 // Explain the action on hover, keyboard focus, or a touch hold.
 let ownHelpTimer,ownHelpTip,ownHelpButton,ownHeld=false;
 const hideOwnHelp=()=>{clearTimeout(ownHelpTimer);ownHelpTip?.remove();ownHelpTip=null;if(ownHelpButton)ownHelpButton.removeAttribute('aria-describedby');ownHelpButton=null;};
 const showOwnHelp=button=>{hideOwnHelp();if(!button.isConnected)return;ownHelpButton=button;ownHelpTip=document.createElement('div');ownHelpTip.id='expert-own-tooltip';ownHelpTip.className='action-hold-tooltip';ownHelpTip.role='tooltip';ownHelpTip.textContent='Выделите фрагмент документа и нажмите кнопку.';document.body.append(ownHelpTip);button.setAttribute('aria-describedby',ownHelpTip.id);const r=button.getBoundingClientRect(),box=ownHelpTip.getBoundingClientRect();ownHelpTip.style.left=Math.max(8,Math.min(r.left,innerWidth-box.width-8))+'px';ownHelpTip.style.top=Math.max(8,r.bottom+box.height+8<=innerHeight?r.bottom+8:r.top-box.height-8)+'px';};
 document.addEventListener('pointerover',e=>{const b=e.target.closest('[data-expert-own]');if(b&&e.pointerType!=='touch'&&!b.contains(e.relatedTarget))ownHelpTimer=setTimeout(()=>showOwnHelp(b),450);});
 document.addEventListener('pointerout',e=>{const b=e.target.closest('[data-expert-own]');if(b&&!b.contains(e.relatedTarget))hideOwnHelp();});
 document.addEventListener('focusin',e=>{if(e.target.matches('[data-expert-own]'))showOwnHelp(e.target);});
 document.addEventListener('focusout',e=>{if(e.target.matches('[data-expert-own]'))hideOwnHelp();});
 document.addEventListener('pointerdown',e=>{ownHeld=false;const b=e.target.closest('[data-expert-own]');hideOwnHelp();if(b&&e.pointerType==='touch')ownHelpTimer=setTimeout(()=>{ownHeld=true;showOwnHelp(b);},600);},true);
 document.addEventListener('pointerup',()=>clearTimeout(ownHelpTimer),true);
 document.addEventListener('pointercancel',hideOwnHelp,true);
 document.addEventListener('pointermove',e=>{if(e.pointerType==='touch')clearTimeout(ownHelpTimer);},true);
 document.addEventListener('click',e=>{if(ownHeld&&e.target.closest('[data-expert-own]')){ownHeld=false;e.preventDefault();e.stopImmediatePropagation();}},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape')hideOwnHelp();});
 document.addEventListener('scroll',hideOwnHelp,true);
 window.addEventListener('resize',hideOwnHelp);

 document.addEventListener('selectionchange',()=>{const s=window.getSelection();const doc=document.getElementById('expert-document');if(s&&doc?.contains(s.anchorNode)&&doc.contains(s.focusNode)&&s.toString().trim()){const fragment=s.getRangeAt(0).cloneContents();fragment.querySelectorAll('.quote-source').forEach(node=>node.remove());selection=fragment.textContent;}});
 document.addEventListener('click',e=>{const tab=e.target.closest('[data-case-tab], [data-case-go-conclusion]');if(tab){const root=tab.closest('.expert-case-view'),name=tab.hasAttribute('data-case-go-conclusion')?'conclusion':tab.dataset.caseTab;if(activateCaseTab(name,root)){onTab?.(root.dataset.caseId,name);if(tab.hasAttribute('data-case-go-conclusion'))root.querySelector('[data-case-tab="conclusion"]')?.focus();}return;}const target=e.target.closest('[data-scroll-to]');if(target){const node=document.getElementById(target.dataset.scrollTo);node?.scrollIntoView({behavior:'smooth',block:'start'});node?.querySelector('textarea,button')?.focus({preventScroll:true});return;}const f=form();if(!f)return;const field=f.elements.text,b=e.target.closest('[data-expert-verdict]');if(b){const i=Number(b.dataset.index),comment=document.querySelector('[data-expert-comment="'+i+'"]')?.value||'';if(b.dataset.expertVerdict==='rejected'&&!b.dataset.reasonOpen){const input=document.querySelector('[data-expert-comment="'+i+'"]');if(input){input.required=true;input.closest('label').querySelector('span').textContent='Причина отклонения *';input.focus();}b.dataset.reasonOpen='true';b.textContent='Сохранить отклонение';message('Укажите обязательную причину отклонения и сохраните.');return;}if(b.dataset.expertVerdict!=='confirmed'&&!comment.trim()){message('Добавьте комментарий для отклонения или изменения.');let note=document.querySelector('[data-expert-feedback="'+i+'"]');if(!note){note=document.createElement('p');note.dataset.expertFeedback=String(i);note.setAttribute('role','status');b.closest('.expert-verdicts').after(note);}note.textContent='Добавьте комментарий для отклонения или изменения.';document.querySelector('[data-expert-comment="'+i+'"]')?.focus();return;}const badge=document.querySelector('[data-expert-status="'+i+'"]');
 const feedback=text=>{let node=document.querySelector('[data-expert-feedback="'+i+'"]');if(!node){node=document.createElement('p');node.dataset.expertFeedback=String(i);node.setAttribute('role','status');badge?.closest('article')?.querySelector('.expert-verdicts')?.after(node);}if(node)node.textContent=text;message(text);};
 if(saving){feedback('Дождитесь завершения сохранения и повторите действие.');return;}
 const c=getCase(),previous=readExpertDecisions(c.conclusions.at(-1).text).get(i);
 if(previous?.status===b.dataset.expertVerdict&&previous.comment===comment.trim()){feedback('Это решение уже сохранено.');return;}
 const text=withExpertDecision(field.value,i,b.dataset.expertVerdict,comment);
 if(text.length>15000){feedback('Не удалось сохранить: превышен объём заключения (15000 символов).');return;}
 saving=true;feedback('Сохранение решения…');
 const locked=[field,...document.querySelectorAll('[data-expert-comment], [data-expert-compose], [data-own-save], [data-action="expert-sign"]')].map(node=>({node,disabled:node.disabled}));locked.forEach(({node})=>node.disabled=true);
 const choices=[...document.querySelectorAll('[data-expert-verdict]')];choices.forEach(choice=>choice.disabled=true);
 Promise.resolve().then(()=>save(c.id,text,Number(f.dataset.revision))).then(result=>{
 if(!f.isConnected){onSaved(c.id,text,result,f);return;}
 field.value=text;onSaved(c.id,text,result,f);f.dataset.revision=String(result.revision);
 const sign=document.querySelector('[data-action="expert-sign"]');if(sign)sign.dataset.revision=String(result.revision);
 if(badge)badge.textContent='Решение эксперта: '+(b.dataset.expertVerdict==='rejected'?'Отклонено с комментарием':titles[b.dataset.expertVerdict]);
 for(const choice of choices.filter(choice=>Number(choice.dataset.index)===i))choice.setAttribute('aria-pressed',String(choice===b));
 update();feedback(b.dataset.expertVerdict==='rejected'?'Отклонено с комментарием':'Решение сохранено: '+titles[b.dataset.expertVerdict]+'.');delete b.dataset.reasonOpen;b.textContent=({confirmed:'Подтвердить',rejected:'Отклонить',modified:'Изменить'})[b.dataset.expertVerdict];
 }).catch(error=>{if(f.isConnected)feedback('Не удалось сохранить: '+error.message+' Повторите действие.');}).finally(()=>{saving=false;choices.forEach(choice=>choice.disabled=false);locked.forEach(({node,disabled})=>node.disabled=disabled);if(f.isConnected)update();});return;}

 if(e.target.closest('[data-expert-own]')){const panel=document.getElementById('expert-own-form');if(!panel)return;if(!selection.trim()){const help=document.querySelector('[data-own-help]');if(help)help.hidden=false;return;}if(panel.hidden){panel.querySelector('[data-own-quote]').value=selection.trim()&&getCase().document.text.includes(selection)?selection:'';}panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'nearest'});panel.querySelector('[data-own-quote]').focus();}
 if(e.target.closest('[data-own-cancel]'))document.getElementById('expert-own-form').hidden=true;
 if(e.target.closest('[data-own-save]')){const panel=document.getElementById('expert-own-form'),inputs=[...panel.querySelectorAll('textarea')];if(!inputs.every(input=>input.reportValidity()))return;if(saving)return;const [quote,assessment,recommendation]=inputs.map(input=>input.value.trim());if(!quote||!assessment||!recommendation){panel.querySelector('[data-own-status]').textContent='Заполните все поля.';return;}const text=field.value+'\n\nСОБСТВЕННЫЕ ЗАМЕЧАНИЯ\nФрагмент / пункт: '+quote+'\nПравовая оценка: '+assessment+'\nРекомендация: '+recommendation;if(text.length>15000){panel.querySelector('[data-own-status]').textContent='Превышен допустимый объём заключения (15000 символов).';return;}saving=true;const button=panel.querySelector('[data-own-save]');button.disabled=true;save(getCase().id,text,Number(f.dataset.revision)).then(result=>{if(!f.isConnected)return;change(text);f.dataset.revision=String(result.revision);const sign=document.querySelector('[data-action="expert-sign"]');if(sign)sign.dataset.revision=String(result.revision);onSaved(getCase().id,text,result,f);panel.hidden=true;inputs.forEach(input=>input.value='');const list=document.querySelector('.expert-own-findings');if(list){const item=document.createElement('div');item.className='conclusion-text';item.textContent='Фрагмент / пункт: '+quote+'\nПравовая оценка: '+assessment+'\nРекомендация: '+recommendation;list.append(item);}const doc=document.getElementById('expert-document');if(doc)doc.innerHTML=highlightedDocument(getCase().document.text,getCase().run.findings,ownQuotes(text));message('Собственное замечание сохранено в дело.');}).catch(error=>{panel.querySelector('[data-own-status]').textContent='Не удалось сохранить: '+error.message;}).finally(()=>{saving=false;button.disabled=false;});}

 if(e.target.closest('[data-expert-compose]')){const outcome=document.querySelector('input[name="expert-outcome"]:checked')?.value,comment=document.getElementById('expert-recommendations').value;if(!outcome){document.querySelector('input[name="expert-outcome"]')?.focus();return;}const text=composeConclusion(field.value,outcome,comment),previous=field.value.match(/^ВЫВОД ЭКСПЕРТА\n[\s\S]*?(?=^РАССМОТРЕНИЕ ЗАМЕЧАНИЙ\n|^СОБСТВЕННЫЕ ЗАМЕЧАНИЯ\n|$(?![\s\S]))/m)?.[0]?.trim();
 const apply=()=>{if(text.length>15000){message('Превышен допустимый объём заключения (15000 символов).');return;}change(text);generated.set(f,conclusionSection(outcome,comment));field.closest('label').hidden=false;field.scrollIntoView({behavior:'smooth',block:'center'});field.focus({preventScroll:true});};
 if(previous&&previous!==generated.get(f)&&text!==field.value){let dialog=document.getElementById('expert-compose-warning');if(dialog)dialog.remove();dialog=document.createElement('dialog');dialog.id='expert-compose-warning';dialog.setAttribute('aria-labelledby','expert-compose-warning-title');dialog.innerHTML='<h2 id="expert-compose-warning-title">Сформировать заключение заново?</h2><p>В заключении есть ваши изменения. Сформировать его заново? Ручные изменения будут потеряны.</p><button type="button" data-compose-cancel>Отмена</button> <button type="button" data-compose-confirm>Сформировать заново</button>';document.body.append(dialog);const close=()=>{dialog.close();dialog.remove();document.querySelector('[data-expert-compose]')?.focus();};dialog.querySelector('[data-compose-cancel]').onclick=close;dialog.querySelector('[data-compose-confirm]').onclick=()=>{close();apply();};dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal();dialog.querySelector('[data-compose-cancel]').focus();return;}apply();}});
 document.addEventListener('input',e=>{if(e.target.closest('#expert-draft-form')){onDirty();update();}else if(e.target.matches('[data-expert-comment]')){onDirty();message('Для сохранения комментария выберите решение по замечанию.');}});document.addEventListener('keydown',e=>{const t=e.target.closest('[data-scroll-to]');if(t&&['Enter',' '].includes(e.key)){e.preventDefault();t.click();}});new MutationObserver(update).observe(document.getElementById('app'),{childList:true});update();
 setInterval(async()=>{const f=form(),c=getCase();if(!f||!c||saving||c.role!=='expert'||c.conclusions.at(-1)?.status!=='draft')return;const text=f.elements.text.value;if(!text.trim()||text===c.conclusions.at(-1).text)return;saving=true;try{const result=await save(c.id,text,Number(f.dataset.revision));if(f.isConnected){f.dataset.revision=String(result.revision);const b=document.querySelector('[data-action="expert-sign"]');if(b)b.dataset.revision=String(result.revision);message('Сохранено в '+new Date().toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow'})+' МСК');}onSaved(c.id,text,result,f);}catch(error){message('Не удалось сохранить: '+error.message+' Текст остаётся в черновике.');}finally{saving=false;}},30000);
}

